"""stages.feedback: generated by the graph.py split (P1)."""

from __future__ import annotations

import json
import re
from typing import Any

from .. import isa
from ..flow import gates, optimize
from ..runtime import llm, parsing
from ..runtime.observations import HARNESS_FAILURE_CATEGORIES
from ..state import CfuDesignState




# sbt/SpinalHDL print the diagnostic BEFORE a long stack trace. Keeping only the
# tail of the output then retains dozens of "at ..." frames while dropping the one
# line that explains the failure, which makes a hardware repair loop blind.
#
# Observed shapes (from real run logs and the SpinalHDL sources):
#   elaboration error          [error] Exception in thread "main" spinal.core.SpinalExit:
#                              [error]  Error detected in phase PhaseNormalizeNodeInputs
#                              [error] ********************  (banner, dropped)
#                              [error] WIDTH MISMATCH (32 bits <- 31 bits) on ...
#                              [error] - Left  operand : (UInt -> Bits of 31 bits)
#                              [error] - Right operand : (toplevel/... : Bits[32 bits])
#                              [error]   at
#                              [error]     at <design>.scala:155   <- first source location
#                              ... ~100 more frames             <- dropped
#                              [error] Design's errors are listed above.
#   pending error              [error] Vec address width mismatch.
#                              [error] - Vec : vectorRegs : Vec of 1 elements
#                              [error] - Address width : 1
#   Scala compile error        [error] /path/File.scala:14:46: not found: type X
#                              [error]   <source echo>             <- context, window only
#                              [error] one error found
#   simulation assertion       [info] [Error] Simulation failed at time=421
#                              [error] Exception in thread "main" java.lang.AssertionError: ...
#   yosys                      [error] ERROR: ...
# The sbt level prefix is not reliable ([info] [Error] ... is a real simulation
# failure), and SpinalHDL error text is often lower case ("... mismatch."), so the
# classifier keys on the message body, not only on the level tag.
_SBT_LEVEL_RE = re.compile(r"^\[(?:error|warn|info|success)\]\s?")


_ERROR_LEVEL_RE = re.compile(r"^\[(?:error|warn)\]")


_INNER_ERROR_RE = re.compile(r"\[(?:Error|Warning)\]|\bERROR:")


_STACK_FRAME_RE = re.compile(r"^\s*at\s")


_SPINAL_BANNER_RE = re.compile(r"^\*{8,}$")


_SOURCE_LOCATION_RE = re.compile(r"\S+\.(?:scala|java):\d+(?::\d+)?")


_SPINAL_TOKEN_RE = re.compile(
    r"WIDTH MISMATCH|ASSIGNMENT OVERLAP|OVERLAP|UNASSIGNED|NO DRIVER|"
    r"LATCH DETECTED|COMBINATIONAL LOOP|HIERARCHY VIOLATION|NAME CONFLICT|"
    r"Error detected in phase|Elaboration failed|Design's errors are listed above|"
    r"SpinalExit|SpinalError|PendingError"
)


_SPINAL_DETAIL_RE = re.compile(r"^-\s+\S.*")


_GENERIC_DIAGNOSTIC_RE = re.compile(
    r"mismatch|not found|does not|cannot|undefined|overlap|no such|missing|"
    r"rejected|invalid|failed|failure|assertion|Exception in thread|Caused by:",
    re.IGNORECASE,
)


_SBT_SUMMARY_RE = re.compile(r"errors? found|Compilation failed|Nonzero exit code")


_YOSYS_ERROR_RE = re.compile(r"\bERROR:")


_DIAGNOSTIC_LINE_MAX = 400


_DIAGNOSTIC_CHARS_MAX = 1400


# Files a design agent cannot edit. When a failure points at one of these, the only
# actionable move is to change the design (or report a platform defect), so say so.
_READ_ONLY_PLATFORM_FILES = ("AgentCfuLib.scala",)


_READ_ONLY_NOTE = (
    "read-only platform note: this failure references {name}, which is a read-only "
    "platform file and cannot be edited. Fix the instruction table or datapath in "
    "AgentCfu.scala (or AgentCfuFiber.scala); if the platform itself is wrong, "
    "report the defect instead of editing it."
)


def _read_only_note(text: str) -> str:
    for name in _READ_ONLY_PLATFORM_FILES:
        if name in text:
            return _READ_ONLY_NOTE.format(name=name)
    return ""


def output_excerpt(text: str, limit: int = 2500) -> str:
    """Excerpt a failed command's output for the repair prompt.

    Prioritises the diagnostic lines over the stack trace, so a long failure keeps
    its cause even when the tail window cannot hold it, and always reports the first
    source location (the frame that names the offending file and line). A failure
    located in the read-only platform is labelled as such.
    """
    text = str(text or "")
    note = _read_only_note(text)
    if len(text) <= limit:
        return f"{text}\n\n{note}" if note else text
    diagnostics: list[str] = []
    frames: list[str] = []
    for raw in text.splitlines():
        if not (_ERROR_LEVEL_RE.match(raw) or _INNER_ERROR_RE.search(raw)):
            continue
        body = _SBT_LEVEL_RE.sub("", raw).strip()
        if not body or _SPINAL_BANNER_RE.match(body):
            continue
        if _STACK_FRAME_RE.match(body):
            if _SOURCE_LOCATION_RE.search(body):
                frames.append(body)
            continue
        if not (
            _SPINAL_TOKEN_RE.search(body)
            or _SPINAL_DETAIL_RE.match(body)
            or _GENERIC_DIAGNOSTIC_RE.search(body)
            or _SOURCE_LOCATION_RE.search(body)
            or _SBT_SUMMARY_RE.search(body)
            or _YOSYS_ERROR_RE.search(body)
        ):
            continue
        line = body[:_DIAGNOSTIC_LINE_MAX]
        if line not in diagnostics:
            diagnostics.append(line)

    def frame_rank(frame: str) -> int:
        """Prefer the frame in project code over framework and stdlib frames."""
        owner = frame[3:].strip() if frame.startswith("at ") else frame
        if re.match(r"^(?:scala|java|javax|sun|sbt|xsbt)\.", owner):
            return 3
        if owner.startswith(("spinal.core.", "spinal.lib.")):
            return 2
        return 1

    location = min(frames, key=frame_rank) if frames else ""
    head_length = limit // 2
    window = f"{text[:head_length]}\n...[truncated]...\n{text[-(limit - head_length):]}"
    parts: list[str] = []
    if diagnostics:
        block = "\n".join(diagnostics)
        if len(block) > _DIAGNOSTIC_CHARS_MAX:
            block = block[:_DIAGNOSTIC_CHARS_MAX] + "\n...[more diagnostics truncated]"
        parts.append("key diagnostics:\n" + block)
    if location:
        parts.append(f"first source location: {location}")
    if note:
        parts.append(note)
    parts.append(window)
    return "\n\n".join(parts)


def _failure_feedback(result: dict, command: str) -> str:
    """Render typed evidence when present, preserving the legacy tail fallback."""
    observation = result.get("failure_observation") or {}
    if observation:
        locations = ", ".join(observation.get("source_locations") or [])
        return (
            f"$ {command}\n"
            f"failure: {observation.get('id', '')} category={observation.get('category', '')}\n"
            f"signature: {observation.get('signature', '')}\n"
            f"source locations: {locations or '(none)'}\n"
            f"summary:\n{observation.get('summary', '')}\n"
            f"full log: {observation.get('log_path', result.get('log_path', ''))}"
        ).strip()
    stdout = output_excerpt(result.get("stdout_tail", ""), 2500)
    stderr = output_excerpt(result.get("stderr_tail", ""), 1500)
    return f"$ {command}\n{stdout}\n{stderr}".strip()


def check_feedback(state: CfuDesignState, rung: str, *, limit: int = 2) -> str:
    """Bounded structured evidence (or legacy tails) for one validation rung."""
    chunks: list[str] = []
    start = int((state.get("repair_evidence_epoch") or {}).get("validation_results", 0))
    for result in (state.get("validation_results") or [])[start:]:
        if result.get("cancelled") or result.get("status") == "cancelled":
            continue
        if result.get("rung") != rung:
            continue
        if result.get("returncode") == 0 and not result.get("skipped"):
            chunks.clear()  # A successful recheck resolves earlier build failures.
            continue
        if result.get("returncode") is None:
            continue
        command = str(result.get("command", ""))[:200]
        chunks.append(_failure_feedback(result, command))
    return "\n\n".join(chunks[-limit:])


def cost_feedback(state: CfuDesignState, *, limit: int = 2) -> str:
    """Tail of the failing Yosys cost commands.

    ``estimate_cost`` records its commands in ``cost_results`` instead of
    ``validation_results``, so the ladder needs a separate reader to feed a
    cost failure into the hardware repair prompt.
    """
    chunks: list[str] = []
    start = int((state.get("repair_evidence_epoch") or {}).get("cost_results", 0))
    for result in (state.get("cost_results") or [])[start:]:
        if result.get("cancelled") or result.get("status") == "cancelled":
            continue
        if result.get("returncode") == 0 and not result.get("skipped"):
            chunks.clear()
            continue
        if result.get("returncode") is None:
            continue
        command = str(result.get("command", ""))[:200]
        chunks.append(_failure_feedback(result, command))
    return "\n\n".join(chunks[-limit:])


def repair_route_guidance(*, tool_mode: bool = False) -> str:
    """Layer choice belongs to the existing implementation repair interaction."""
    common = (
        "\nREPAIR LAYER SELECTION: use current failure evidence to decide whether the defect "
        "is implementation, ISA/semantic contract, or workload analysis. An upstream rewind "
        "rolls back this round's source/oracle edits, abandons the frozen contract, clears "
        "dependent validation/reuse and spends one existing design-repair slot; contract "
        "answer retries do not provide free route changes. No route changes on first delivery.\n"
    )
    if tool_mode:
        return common + (
            "After submit_repair_diagnosis, call request_repair_route(target=analysis|contract|implement, "
            "reason, failure_ids). Cite exact current IDs from that diagnosis. analysis/contract "
            "close this transaction: call submit_stage with a short rewind summary, not a patch. "
            "implement stays in this same round and requires real edits before submit.\n")
    return common + (
        'Instead of a patch, you may emit REPAIR_ROUTE followed by one JSON object: '
        '{"target":"analysis|contract","reason":"why this layer",'
        '"failure_ids":["current failure id"],"diagnosis":{'
        '"failure_ids":["current failure id"],"observed_errors":["observed message"],'
        '"root_cause":"cause","repair_mapping":["layer change"],"regression_risks":["risk"]}}. '
        'Do not mix an upstream REPAIR_ROUTE with EDIT/FILE/PATCH content. '
        'To stay at implement, deliver the ordinary diagnosed source repair.\n')


def labeled_feedback(label: str, text: str) -> str:
    """Prefix a feedback block with the rung that produced it."""
    text = (text or "").strip()
    return f"### {label}\n{text}" if text else ""


def hardware_repair_feedback(state: CfuDesignState) -> str:
    """Every authoritative error source for a hardware repair, clearly labeled.

    A hardware repair can be triggered by the SoC build, by a repeated
    simulation failure that escalated from software, or by a failed Yosys cost
    run. Each source is labeled so the model can attribute the exact error
    instead of guessing, and empty sources are omitted.
    """
    parts = [
        labeled_feedback("hw_build (SoC generation) errors", check_feedback(state, "hw_build")),
        labeled_feedback("hw_conformance errors", conformance_feedback(state)),
        sim_feedback(state),
        labeled_feedback(f"cost ({'Vivado' if state.get('cost_backend') == 'vivado' else 'Yosys'}) errors", cost_feedback(state)),
        labeled_feedback(
            "implementation_hw rejection", implementation_feedback(state, "implementation_hw")
        ),
    ]
    return "\n\n".join(part for part in parts if part)


def all_failure_feedback(state: CfuDesignState) -> str:
    """Every failing rung's evidence, for the single implementation stage.

    That stage now absorbs repairs from both sides, so it has to see the whole
    picture: the hardware sources (`hardware_repair_feedback` covers hw_build,
    hw_conformance, sim, cost and the hardware rung's own rejection) plus the
    software ones (sw_build, and the software rung's rejection). Each block is
    labeled by the rung that produced it and bounded — no complete log is
    inlined, only the excerpt and the log path.
    """
    parts = [
        hardware_repair_feedback(state),
        labeled_feedback("sw_build (software build) errors", check_feedback(state, "sw_build")),
        labeled_feedback(
            "implementation_sw rejection", implementation_feedback(state, "implementation_sw")
        ),
    ]
    return "\n\n".join(part for part in parts if part)


def implementation_feedback(state: CfuDesignState, rung: str, *, limit: int = 3) -> str:
    """Why the previous attempt at an implementation rung was rejected.

    A build rung reports tool errors through ``validation_results``; an
    implementation rung that produced no usable patch never reaches a tool, so
    its rejection reason is carried on the gate itself. Both feed the next
    prompt.
    """
    gate = (state.get("gates", {}) or {}).get(rung, {}) or {}
    errors = [str(item) for item in (gate.get("errors") or []) if str(item).strip()]
    return "\n".join(errors[-limit:])


def upstream_repair_feedback(state: CfuDesignState) -> str:
    """Carry the diagnosed layer decision to the existing upstream model call."""
    route = state.get("repair_route") or {}
    if route.get("target") not in ("analysis", "contract"):
        return ""
    return (
        "\n## Implementation diagnosis requesting upstream revision\n"
        "The old contract/implementation approvals are invalidated. These cited failures "
        "are historical evidence for this revision, not current claims about new bytes. "
        "Address the diagnosed layer error; do not recreate the old contract unchanged.\n"
        + json.dumps(route, ensure_ascii=False) + "\n")


def isa_repair_feedback(state: CfuDesignState) -> str:
    """Linter problems from the previous ISA contract attempt, if any."""
    problems = [str(item) for item in (state.get("isa_spec_errors") or []) if str(item).strip()]
    return "\n".join(f"- {problem}" for problem in problems)


def _isa_enveloped(text: str) -> bool:
    """True when the response wrapped its contract in an envelope.

    Unwrapping is deliberately lenient, so record it in the run history rather than
    accepting a malformed protocol silently.
    """
    try:
        data = json.loads(text)
    except (json.JSONDecodeError, TypeError):
        return False
    return isinstance(data, dict) and isa.unwrap_isa_contract(data) is not data


def _isa_shape_note(isa_spec: dict) -> str:
    """Report what the parser actually extracted from an ISA response.

    A model that nests the contract (observed: GLM returning {"analysis": ...,
    "roofline": {...}, "isa_contract": "<yaml>"}) otherwise only sees symptoms such
    as "identity.name is required" and re-emits the identical envelope, because
    nothing tells it that its contract WAS present but wrapped.
    """
    if not isinstance(isa_spec, dict):
        return "note: the response did not parse as a mapping"
    keys = ", ".join(str(key) for key in isa_spec.keys()) or "(none)"
    return (
        f"note: the parser read these top-level keys from the response: {keys}. "
        "The contract must BE the top-level object with keys spec_version, identity, "
        "commands, operations_contract, state, memory, datapath, software, integration, "
        "validation, assumptions, unknowns and roofline. Do not nest it under another "
        "key (such as isa_contract) and do not return it as a string."
    )


_SEARCH_BLOCK_RE = re.compile(r"^<<<<<<< SEARCH\s*\n(.*?)^=======", re.MULTILINE | re.DOTALL)


def delivery_search_key(text: str) -> str:
    """Approach fingerprint: the first content line of every SEARCH block.

    Two deliveries that target the same (possibly stale) line repeat one
    approach even when their bytes differ, which a response hash cannot see.
    FILE/PATCH deliveries have no SEARCH blocks and return "".
    """
    keys: list[str] = []
    for block in _SEARCH_BLOCK_RE.findall(text or ""):
        for line in block.splitlines():
            if line.strip():
                keys.append(line.strip())
                break
    if not keys:
        return ""
    return parsing._attempt_digest("\n".join(keys))


def _repeated_delivery_error(attempts: Any, text: str) -> str:
    """Reject a SEARCH delivery that repeats an already-rejected approach.

    Deterministic and cheap: the same first SEARCH line already failed to apply
    once, so replaying it can only fail again and burn a stage turn. The model
    is told to rebuild the edit from the current target content instead.
    """
    key = delivery_search_key(text or "")
    if not key:
        return ""
    entries = [item for item in (attempts or []) if isinstance(item, dict)]
    for index, item in enumerate(entries, start=1):
        if item.get("applied"):
            continue
        if str(item.get("search_key") or "") == key:
            return (
                f"REPEATED APPROACH: this SEARCH block repeats the approach of rejected "
                f"attempt {index}, which already failed to apply. Nothing was applied. "
                "Re-read the exact current target content shown in the prompt and build "
                "the edit from THAT text (or deliver the complete file with FILE_BEGIN)."
            )
    return ""


def tool_intent_error(text: str, degraded_reason: str = "") -> str:
    """Explain a response that only announced reading a file.

    This is the shape a tools-enabled model produces when the endpoint refused
    the tools payload (or dropped the tool_calls): the prompt promised tools, so
    it says "Let me read ..." and stops. Without this the rung fails with only a
    generic "no deliverable" message and the repair repeats the same answer.
    """
    if not llm.looks_like_tool_intent(text):
        return ""
    reason = f" (tool calling failed: {degraded_reason})" if degraded_reason else ""
    return (
        "the answer was a tool-intent preamble: it announced reading a file but emitted no "
        f"deliverable and no tool call{reason}. Emit the EDIT_BEGIN/FILE_BEGIN/PATCH_BEGIN "
        "block now, using the content already shown in the prompt."
    )


def _repeated_attempt_directive(attempts: Any) -> str:
    """A blunt instruction when this exact answer already failed this run.

    A rejected response leaves the workspace unchanged, so an unchanged prompt
    can make the model repeat the same answer until the repair budget is gone.
    The last response is compared against EVERY earlier attempt (not just the
    immediately previous one), so an A-B-A oscillation is caught too. Detecting
    it here forces a different delivery strategy on the next try.
    """
    entries = [item for item in (attempts or []) if isinstance(item, dict)]
    if len(entries) < 2:
        return ""
    last = entries[-1]
    repeated = any(
        last.get("response_hash") == earlier.get("response_hash")
        and last.get("error_hash") == earlier.get("error_hash")
        for earlier in entries[:-1]
    )
    if not repeated:
        # Byte-level check misses semantic repetition: the same first SEARCH
        # line re-sent with different surrounding prose (observed 2026-09-29,
        # three deliveries re-fixing one already-fixed compile error).
        last_key = str(last.get("search_key") or "")
        repeated = bool(
            last_key
            and not last.get("applied")
            and any(
                last_key == str(earlier.get("search_key") or "")
                for earlier in entries[:-1]
                if earlier.get("search_key")
            )
        )
        if repeated:
            return (
                "=== REPEATED APPROACH DETECTED ===\n"
                "A previous delivery used the same first SEARCH line and it is stale or "
                "already applied: the target file has changed since. Re-sending it can only "
                "fail again. Re-read the exact current target content shown in the prompt "
                "and build the edit from THAT text, or deliver the complete file with "
                "FILE_BEGIN. Verify each fix is still needed: do not re-apply a change that "
                "earlier attempts already made."
            )
    if not repeated:
        return ""
    return (
        "=== REPEATED IDENTICAL ATTEMPT DETECTED ===\n"
        "You already sent this exact response earlier in this run and it failed with the "
        "identical rejection. Sending it again wastes the remaining repair budget. Change "
        "strategy now:\n"
        "- Prefer Protocol B (FILE_BEGIN) with the complete new file content, or\n"
        "- shrink every SEARCH block to a few unique code lines copied verbatim from the "
        "target content above (no long comment blocks), or\n"
        "- if a SEARCH failed on a comment, use the exact current comment text from above."
    )


def attempt_ledger_block(attempts: Any) -> str:
    """Compact record of earlier attempts for the repair prompt.

    Without it the model sees only the newest failure and can silently repeat a
    strategy that already failed; with it every repair prompt carries what was
    tried and why it was rejected.
    """
    entries = [item for item in (attempts or []) if isinstance(item, dict)]
    if not entries:
        return ""
    lines = ["=== PRIOR ATTEMPTS (do not repeat a rejected approach) ==="]
    for index, item in enumerate(entries, start=1):
        outcome = "applied" if item.get("applied") else "rejected"
        error = str(item.get("error_text") or "").strip() or "(no error detail recorded)"
        lines.append(
            f"{index}. response={item.get('response_hash', '?')} {outcome}: {error[:200]}"
        )
    return "\n".join(lines)


def current_attempts(state: CfuDesignState, key: str) -> list:
    """Old delivery fingerprints remain historical after an upstream rewind."""
    start = int((state.get("repair_evidence_epoch") or {}).get(key, 0))
    return list(state.get(key) or [])[start:]


def software_stuck_directive(state: CfuDesignState) -> str:
    """Stuck-retry directive for the software rung (see _repeated_attempt_directive)."""
    return _repeated_attempt_directive(current_attempts(state, "sw_attempts"))


def hardware_stuck_directive(state: CfuDesignState) -> str:
    """Stuck-retry directive for the hardware rung (see _repeated_attempt_directive).

    The hardware rung used to lack this guard while the software rung had it:
    a model stuck on one byte-identical broken answer burned the whole repair
    budget (observed 2026-09-26, three identical deliveries in a row).
    """
    return _repeated_attempt_directive(current_attempts(state, "hw_attempts"))


def conformance_feedback(state: CfuDesignState) -> str:
    """Failure lines from the conformance micro-test, for the hardware repair."""
    gate = gates._rung_gate(state, "hw_conformance")
    chunks = [str(item) for item in (gate.get("errors") or []) if str(item).strip()]
    chunks.extend(str(item) for item in (gate.get("details") or []) if str(item).strip())
    return "\n".join(chunks)


def conformance_oracle_directive(state: CfuDesignState) -> str:
    """Flag an oracle rejection the model has already produced before.

    An oracle repair that varies one field at a time oscillates between two
    errors (fix the arg count, break the arg literals; fix the literals,
    re-add the extra arg; keep inventing the same intrinsic name) and burns the
    whole budget. A rejection recurring is the signal to satisfy every
    constraint at once.
    """
    attempts = [
        item for item in current_attempts(state, "conformance_attempts") if isinstance(item, dict)
    ]
    if len(attempts) < 2:
        return ""
    earlier = {item.get("problems_hash") for item in attempts[:-1]}
    if attempts[-1].get("problems_hash") not in earlier:
        return ""
    return (
        "=== REPEATED ORACLE REJECTION DETECTED ===\n"
        "This exact rejection (validator failure or generated-test build/link failure) has "
        "already occurred in this run. Varying one field at a time only oscillates between "
        "the errors; satisfy every constraint at once:\n"
        "- `cases[i].args` holds EXACTLY one integer literal per declared CPU-value role "
        "(rs1, then rs2). Casts, addresses, identifiers and expressions are rejected: the "
        "harness embeds each arg as a compile-time constant into the generated intrinsic "
        "call.\n"
        "- Any address or data preparation belongs in `setup` (plain C statements); seed "
        "the vectors there and give the argument a literal value, e.g. `args: [0]`.\n"
        "- The oracle's C may call ONLY the generated intrinsics named in the command "
        "table plus `cfu_enable`/`cfu_memory_fence`; an invented name such as `cfu_load` "
        "is an `undefined reference` at link time.\n"
        "- `reference`/`verify` and the vector `setup` requirements are unchanged."
    )


def _tool_diagnostics(*results: dict) -> str:
    """Error-shaped lines from command output, for repair feedback.

    The conformance build failure used to report only the make command line, so
    the oracle repair could not see ``undefined reference to `cfu_load'`` and
    repeated the same invented intrinsic until the budget was gone.
    """
    lines: list[str] = []
    for result in results:
        if not isinstance(result, dict):
            continue
        text = f"{result.get('stdout_tail') or ''}\n{result.get('stderr_tail') or ''}"
        for line in text.splitlines():
            if re.search(r"error|undefined reference|multiple definition|ld returned|fatal", line, re.I):
                cleaned = line.strip()
                if cleaned and cleaned not in lines:
                    lines.append(cleaned)
    return "\n".join(lines[:40])


def conformance_build_error(build: dict, build_argv: list[str]) -> str:
    """The build-failure rejection message, with the compiler/linker output."""
    message = f"conformance test build failed: {' '.join(build_argv)[:200]}"
    diagnostics = _tool_diagnostics(build)
    return message + (f"\nbuild diagnostics:\n{diagnostics}" if diagnostics else "")


def conformance_sim_error(sim: dict, diagnostics: str) -> str:
    """Evidence-based first line for a failed conformance simulation.

    The previous wording claimed "the CPU reached the fail symbol" for every
    non-zero exit, which misattributed simulator-harness crashes to the design.
    The first line now matches what the log actually shows; the raw diagnostics
    are still attached below it.
    """
    category = str(((sim.get("failure_observation") or {}).get("category")) or "")
    text = f"{sim.get('stdout_tail') or ''}\n{sim.get('stderr_tail') or ''}".lower()
    if category == "fail_symbol" or (not category and "fail symbol" in text):
        head = "conformance simulation failed (the CPU reached the fail symbol)"
    elif category == "assertion":
        head = (
            "conformance simulation hit an HDL assertion failure: "
            "a hardware contract check was violated (see the named assertion)"
        )
    elif category == "liveness_timeout":
        head = (
            "conformance simulation hit the CPU commit-progress watchdog; this is a "
            "repairable progress failure, not automatically a simulation-harness crash. "
            "Check CFU completion/backpressure, counters and operand-dependent latency; "
            "inspect test counts/lengths and use small bounded cases. A long operation "
            "and a deadlock are both possible; do not claim a value mismatch without "
            "a differential verdict or disable the watchdog to hide the failure."
        )
    elif category == "sim_harness_crash":
        head = (
            "conformance simulation crashed inside the simulation harness "
            "(testbench/probe exception) before any case verdict; "
            "this is not evidence about the CFU design"
        )
    elif category == "timeout":
        head = "conformance simulation timed out before reaching the pass or fail symbol"
    else:
        head = "conformance simulation failed without reaching the pass or fail symbol"
    return head + (f"\nsimulation diagnostics:\n{diagnostics}" if diagnostics else "")


def conformance_repair_target(oracle_failure: bool, results: list[dict]) -> str | None:
    """Where a failed conformance rung routes, or None when nothing can repair it.

    Only a test that ran and disagreed with its reference is design evidence.
    A simulation-harness/environment failure produced no case verdict, so it
    must not burn a design repair budget.
    """
    harness_failure = any(
        str(((r.get("failure_observation") or {}).get("category")) or "")
        in HARNESS_FAILURE_CATEGORIES
        for r in results
    )
    if harness_failure:
        return None
    return "implement"  # oracle errors are conformance-only work in Implement, never Verify writes


def _rejection_attempt(problems: list[str], result_text: str = "") -> dict | None:
    """Ledger entry for a rejected oracle (validator problems or its build).

    Hashes the diagnostic-shaped lines, so an identical failure recurs even if
    incidental make chatter differs between attempts.
    """
    if not problems:
        return None
    key_lines = [
        line for line in problems
        if re.search(r"error|fail|undefined reference|rejected|must be|unknown", line, re.I)
    ] or list(problems)
    return {
        "problems_hash": parsing._attempt_digest("\n".join(key_lines)),
        "response_hash": parsing._attempt_digest(result_text),
    }


def sim_attribution(results: list[dict], sim_text: str) -> str:
    """A short, actionable cause for a failed emulation run.

    MiCoSocSim only reports that the CPU reached the pass/fail symbol, which is
    true but useless for a repair. This maps the log (and the harness's verify
    diagnostic) to a concrete cause.
    """
    lowered = sim_text.lower()
    verify: dict = {}
    for result in results:
        candidate = (result.get("parsed") or {}).get("verify")
        if isinstance(candidate, dict):
            verify = candidate
    if verify.get("status") == "fail":
        benchmark = str(verify.get("benchmark", "the benchmark"))
        code = verify.get("verify")
        detail = f" (verify_benchmark returned {code})" if code is not None else ""
        return (
            f"Embench verify failed for {benchmark}{detail}: the accelerated (CFU) build "
            "computed a different observable result from the scalar reference. This is a "
            "wrong-result failure, not a build error, a crash, or a harness problem."
        )
    if "fail symbol" in lowered:
        return (
            "the software reached the fail symbol, i.e. main() returned non-zero because "
            "verify_benchmark() rejected the result: the CFU build produced a wrong value "
            "(correctness), not a build or harness failure."
        )
    if any(result.get("timed_out") for result in results):
        return (
            "the simulation timed out before reaching the pass/fail symbol: likely a hang "
            "(unfinished TileLink transaction, a wait on a fence, or a non-terminating loop)."
        )
    if verify.get("status") == "pass":
        # Correctness passed: any remaining failure is the rung's own gate (for
        # example the speedup floor), which already reports itself.
        return ""
    if results and all(result.get("returncode") in (0, None) for result in results):
        return ""
    return (
        "the simulation ended without reaching the pass or fail symbol; check the log for a "
        "trap/exception or a simulator error."
    )


def sim_feedback(state: CfuDesignState) -> str:
    """Simulation feedback for a repair prompt: attribution first, then the log."""
    gate = (state.get("gates", {}) or {}).get("sim") or {}
    attribution = str(gate.get("attribution", "") or "")
    # When the router picked this rung, carry its diagnosis so the repair works on
    # the named defect instead of re-deriving the failure from the log.
    decision = gate.get("repair_decision") or {}
    routing = ""
    if isinstance(decision, dict) and decision.get("source") == "llm":
        cause = str(decision.get("root_cause", "") or "").strip()
        reason = str(decision.get("reason", "") or "").strip()
        if cause or reason:
            routing = (
                f"Repair routing assigned this failure to {decision.get('target')}: "
                f"{cause or reason}"
            )
    log = check_feedback(state, "sim")
    return labeled_feedback(
        "sim (simulation) errors", "\n\n".join(p for p in (attribution, routing, log) if p)
    )


def optimization_directive(state: CfuDesignState) -> str:
    """The instructions a rung gets when it runs as an optimization round."""
    plan = state.get("optimization_plan") or {}
    if not isinstance(plan, dict) or not plan:
        return ""
    focus = str(plan.get("focus", "") or "performance")
    goal = {
        "cost": "reduce the synthesized CFU cost (area) without losing performance",
        "performance": "raise the measured speedup without growing the hardware",
    }.get(focus, "improve the measured result")
    return (
        f"Round {plan.get('round', '?')} focus: {goal}.\n"
        f"Current validated result: {optimize.optimization_score(state)}\n"
        f"Planner's reason: {plan.get('reason', '')}\n"
        "Change one thing and keep everything the software already relies on: the ISA "
        "contract is frozen for this implementation attempt; only the extend_isa node "
        "may append commands before hardware/software implementation. Do not alter the "
        "accepted contract here. "
        + ("Implement and use the new instruction(s): " + ", ".join(state.get("isa_added_symbols") or [])
           if plan.get("target") == "extend_isa" else "")
    )
